import org.jsoup.nodes.*;
import org.jsoup.parser.Token.*;

import org.junit.Test;

import java.io.StringReader;

import static org.junit.Assert.*;

public class XmlTreeBuilderTest {
    @Test
    public void InitialiseParseTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        testObject.initialiseParse(new StringReader("<fruit>Apple</fruit>"), "BaseUri", new Parser(testObject));
        assertNotNull(testObject.getStack());
        Document.OutputSettings outputSettings = testObject.getStack().get(0).outputSettings();
        assertEquals(Document.OutputSettings.Syntax.xml, outputSettings.syntax());
        assertEquals(Entities.EscapeMode.xhtml, outputSettings.escapeMode());
        assertFalse(outputSettings.prettyPrint());
    }

    @Test
    public void NewInstanceTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        assertNotNull(testObject.newInstance());
    }

    @Test
    public void ProcessStartTagTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        StartTag startTag = new StartTag("test");
        Token testToken = new Token(startTag);
        assertTrue(testObject.process(testToken));
    }

    @Test
    public void ProcessEndTagTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        EndTag endTag = new EndTag("test");
        Token testToken = new Token(endTag);
        assertTrue(testObject.process(testToken));
    }

    @Test
    public void ProcessDoctypeTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        Doctype doctype = new Doctype("testTitle", "testPublicId", "testSystemId", "testPubSysKey");
        Token testToken = new Token(doctype);
        assertTrue(testObject.process(testToken));
    }

    @Test
    public void ProcessCommentTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        Comment comment = new Comment("testComment");
        Token testToken = new Token(comment);
        assertTrue(testObject.process(testToken));
    }

    @Test
    public void ProcessCharacterTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        Character character = new Character("testData", false);
        Token testToken = new Token(character);
        assertTrue(testObject.process(testToken));
    }

    @Test
    public void InsertTokenCommentTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        Comment comment = new Comment("testComment");
        testObject.insert(new Token(comment));
        assertEquals("testComment", ((Comment) testObject.getCurrentElement().childNode(0)).getData());
    }

    @Test
    public void InsertTokenStartTagTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        StartTag startTag = new StartTag("test");
        testObject.insert(new Token(startTag));
        assertEquals("test", testObject.getCurrentElement().childNode(0).nodeName());
    }

    @Test
    public void InsertTokenCharacterTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        Character character = new Character("testData", false);
        testObject.insert(new Token(character));
        assertEquals("testData", ((TextNode) testObject.getCurrentElement().childNode(0)).getWholeText());
    }

    @Test
    public void ParseFragmentWithNoContextTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        Parser parser = new Parser(testObject);
        List<Node> nodes = testObject.parseFragment("<fruit>Apple</fruit>", "http://example.com", parser);
        assertEquals("fruit", nodes.get(0).nodeName());
        assertEquals("Apple", ((Element) nodes.get(0)).text());
    }

    @Test
    public void ParseFragmentWithContextTest() {
        XmlTreeBuilder testObject = new XmlTreeBuilder();
        Parser parser = new Parser(testObject);
        Document doc = Document.createShell("http://example.com");
        Element context = doc.appendElement("tree");
        List<Node> nodes = testObject.parseFragment("<fruit>Apple</fruit>", context, "http://example.com", parser);
        assertEquals("fruit", nodes.get(0).nodeName());
        assertEquals("Apple", ((Element) nodes.get(0)).text());
    }
}
